}

class Family {
    public static void main(String[] args) {
        List<FamilyMember> members = List.of(
            new FamilyMember("Grandpa", 70, true),
            new FamilyMember("Dad", 45, true),
            new FamilyMember("Mom", 42, true),
            new FamilyMember("Uncle", 35, false),
            new FamilyMember("Son", 16, false)
        );

        Predicate<FamilyMember> isAdult = m -> m.age >= 18;
        Function<FamilyMember, String> getRole = m -> m.isParent ? "Parent" : "NonParent";

        long count = members.stream()
            .filter(isAdult.negate())
            .map(getRole)
            .filter(role -> role.equals("NonParent"))
            .count();

        System.out.println(count);
    }
}

