class FamilyVacation {
    private String destination = "Paris";
    private static String season = "Summer";

    public void planTrip() {
        String budget = "5000";
        int familySize = 4;

        List<Supplier<String>> plans = new ArrayList<>();

        for (int day = 1; day <= 2; day++) {
            String activity = "Day" + day;
            int localDay = day;

            plans.add(() -> activity + ":" + localDay);  // Line A
        }

        budget = "6000";
        this.destination = "Rome";
        season = "Winter";
        familySize++;

        Supplier<String> tripInfo = () -> {
            String budget = "7000";  // Line B
            return destination + "-" + season + "-" + budget + "-" + familySize;
        };

        plans.add(tripInfo);
        plans.add(this::getDestination);  // Line C

        destination = "London";

        plans.forEach(p -> System.out.print(p.get() + " "));
    }

    private String getDestination() {
        return destination;
    }

    public static void main(String[] args) {
        new FamilyVacation().planTrip();
    }
}

