class FamilyMember extends Thread {
    private String name;
    private static final Object kitchen = new Object();

    FamilyMember(String name) { this.name = name; }

    public void run() {
        System.out.println(name + " wants to cook");
        synchronized(kitchen) {
            System.out.println(name + " is cooking");
            try {
                Thread.sleep(5000); // cook for 5 seconds
            } catch(InterruptedException e) {
                System.out.println(name + " interrupted while cooking");
            }
            System.out.println(name + " finished cooking");
        }
    }
}

